use super::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_native_decoding::native_decoding::OriginalEffectReply;

fn fields(index:usize)->Option<NativeRecordSchema>{(index==0).then_some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"alpha",ordinal:0}))}
#[test]
fn native_descriptor_denial_preserves_the_unpublished_destination(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️descriptor.json")).unwrap();let stock=serde_json::json!({"items":8,"copyBytes":4096,"capacityBytes":0,"releaseBytes":0,"depth":8,"fuel":8,"maximumTurns":8});let mut bank=EffectBank::new(Wallet::from_profile(&stock));let descriptor=unsafe{NativeSchemaFields::native(fields)};let demand=NativeSchemaFields::selection_demand();let mut destination=None;
 let denied=bank.loan(1,demand.copy_bytes-1);let mut reply=None;let(poll,actual)=bank.run(denied,1,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(descriptor.select_into(0,&mut destination,effect,token).unwrap());engine::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})});let engine::RetainedWorkPoll::Complete(turn)=poll else{panic!("descriptor denial remained pending")};assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert!(destination.is_none());assert_eq!(reply.as_ref().unwrap().as_ref().unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actual,None);assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied,(0,0));
 let grant=bank.loan(1,demand.copy_bytes);let mut reply=None;let(poll,actual)=bank.run(grant,1,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(descriptor.select_into(0,&mut destination,effect,token).unwrap());engine::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})});let engine::RetainedWorkPoll::Complete(turn)=poll else{panic!("descriptor selection remained pending")};assert_eq!(turn.work,u128::from(law["work"].as_u64().unwrap()));let Some(Some(NativeRecordSchema::Leaf(leaf)))=destination else{panic!("expected selected leaf")};assert_eq!(leaf.name,"alpha");let progress=reply.take().unwrap().unwrap().progress();assert_eq!(progress.copied_bytes,demand.copy_bytes);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));
 let grant=bank.loan(1,demand.copy_bytes);let mut missing=None;let mut reply=None;let(poll,actual)=bank.run(grant,1,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(descriptor.select_into(1,&mut missing,effect,token).unwrap());engine::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})});let engine::RetainedWorkPoll::Complete(turn)=poll else{panic!("missing descriptor selection remained pending")};assert_eq!(turn.work,u128::from(law["work"].as_u64().unwrap()));assert!(matches!(missing,Some(None)));assert_eq!(law["unavailable"],"missing");let progress=reply.as_ref().unwrap().as_ref().unwrap().progress();assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,(0,0));
}
